--[=[
	@class WuKong
	@client


	本类为悟空客户端入口

	
	```lua
	-- 引用悟空客户端门面
	require(game.ReplicatedStorage.Packages.WuKong)
	```

	:::caution

	`require()` 本模块时, 会自动等待悟空框架准备好. 这是一个 **yields** 过程.

	:::
	

]=]

if not game["Run Service"]:IsClient() then
	return {}
end

local rs = game:GetService("ReplicatedStorage")
require(rs.Packages.c2l)
local WuKongClientCSharp = _G.wdm.WuKong.RbxClient.WuKongClient
local Env = require(game.ReplicatedStorage.Packages.DotEnv)
local WuKongFacade = require(script.WuKongFacade)

print("Start WuKong")

script:WaitForChild("RemoteActionFunction")

script:WaitForChild("RemoteCommandFunction")

script:WaitForChild("Configuration")

-- start server
local devUserId = nil
if Env.GetUserId then
	devUserId = tostring(Env.UserId)
end
local facade: WuKongFacade.Type = WuKongClientCSharp.Start(Env.IsClientDev, devUserId)

local debugger = nil

-- 允许使用Debugger
-- checkAdminHandler: 检查是否是管理员的回调函数
-- options: 默认 toogleKey: Enum.KeyCode.F6, minimizeKey: Enum.KeyCode.F7
facade.EnableDebugger = function(
	checkAdminHandler: () -> boolean,
	options: {
		toggleKey: Enum.KeyCode?,
		minimizeKey: Enum.KeyCode?,
	}?
)
	if checkAdminHandler and checkAdminHandler() then
		debugger = require(script.WuKongDebugger).new(options)
	end
end

return facade
